New metrics emitted at end-of-prefill (pseudo):

// prefill_tokens and reused_tokens are tracked during prefill planning
int64_t wasted = std::max<int64_t>(0, prefill_tokens - reused_tokens_observed);
metrics::Histogram("runtime.cache.wasted_prefill_tokens").Observe(wasted, tags);
metrics::Counter("runtime.cache.wasted_prefill_requests_total").Inc(1, tags.With("miss_reason", reason));
if (eviction_observed) metrics::Counter("runtime.cache.wasted_prefill_eviction_correlated_total").Inc(1, low_card_tags);
if (pressure_observed) metrics::Counter("runtime.cache.wasted_prefill_pressure_correlated_total").Inc(1, low_card_tags);

Notes: tags are allowlisted (model, model_version, route_id, deployment_mode, region, prompt_len_bucket) and do not include tenant_id.
